package com.example.examplemod;

import com.tterrag.registrate.Registrate;
import com.tterrag.registrate.util.entry.ItemEntry;

import net.minecraft.world.item.Item;
import net.minecraft.world.item.Rarity;

public class AllItems {
    private static final Registrate REGISTRATE = ExampleMod.getRegistrate();

    // the copper gear works like totem of undying
    // it is NOT a tech mod, but it gets generated by copper machine.
    public static final ItemEntry<Item> COPPER_GEAR = REGISTRATE
        .item("copper_gear", Item::new)
        // balancing: you can stack up to 16, and it loses durability constantly.
        .properties(p -> p.stacksTo(16)
            .rarity(Rarity.EPIC)
            .fireResistant())
        .lang("Copper Gear")
        .register();
    
    public static void register() {}
}
